{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "m-AMSA, the closest analogue sharing the methanesulfonamide and fused acridine-like aromatic system, had CSF concentrations only 1-3% of plasma after IV dosing in rhesus monkeys, directly demonstrating poor BBB access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Compound 24, containing an aryl methanesulfonamide and a phenyl-substituted fused heteroaromatic, showed a rat brain-to-plasma ratio of 0.07, indicating low CNS penetration despite substantial lipophilic surface.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The PK11195-type isoquinoline carboxamide, structurally related to the query's carboxamide core, showed relatively low brain uptake in PET, showing that lipophilic fused carboxamides do not automatically achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A chiral N-(1-phenylpropyl) carboxamide (38a) had excellent brain penetration and no P-gp efflux, but it lacks the ionizable methanesulfonamide and has a smaller, less polar heteroaromatic core, limiting transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "PK11195 is reported to cross the intact BBB and bind TSPO in the brain, showing that the isoquinoline carboxamide scaffold can be brain-penetrant; however, this is outweighed by the query's additional ionizable sulfonamide and larger polar surface.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted to have inadequate CNS access. The closest direct experimental analogue (m-AMSA) shows very low CSF penetration, and another sulfonamide-fused heteroaromatic has a B/P ratio of 0.07. These direct measurements outweigh the weaker contradictory examples that lack the query's acidic sulfonamide and larger polar surface. The computed low neutral fraction and high TPSA are consistent with this fail prediction.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF measurement exists for the exact query molecule.",
    "Morgan similarities to the most relevant evidence are modest (0.26-0.32), so transfer is not exact.",
    "Conflicting PK11195 records (low brain uptake vs. rapid BBB crossing) create uncertainty about how much the carboxamide scaffold alone contributes.",
    "No experimental P-gp/BCRP efflux data are available for the query; efflux could further reduce CNS exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

